std::string native_hex_name(const std::string& value){std::ostringstream out;out<<std::hex<<std::setfill('0');for(unsigned char c:value)out<<std::setw(2)<<static_cast<unsigned int>(c);return out.str();}
std::string native_signature(const FunctionDecl& function){std::string out=function.name+"(";for(std::size_t i=0;i<function.params.size();++i){if(i)out+=',';out+=function.params[i].type.text();}return out+")->"+function.result.text();}
std::string native_symbol(const std::string& module,const FunctionDecl& function){const auto hash=sha256_text(native_signature(function));return"stellar_v01_m"+native_hex_name(module)+"_s"+native_hex_name(function.name)+"_h"+hash.substr(7,16);}

