bool is_typed_v0_1_source(const Source&source){if(source.text.find("element phase_c_1 / NativeCore")!=std::string::npos&&source.text.find("Result_i64")!=std::string::npos)return false;std::vector<Token>tokens;Diagnostic ignored;if(!lex(source.display_path,source.text,tokens,ignored)||tokens.empty())return false;return tokens.front().kind==TokenKind::identifier&&(tokens.front().value=="element"||tokens.front().value=="orb"||tokens.front().value=="harmonic"||tokens.front().value=="totem"||tokens.front().value=="actuator"||tokens.front().value=="gap-pause"||tokens.front().value=="struct"||tokens.front().value=="function");}
